/**
 * Crochet Studio — service worker.
 *
 * Hand-written rather than generated by Workbox: the caching story here is one
 * paragraph long (precache the build, serve it first, keep working with the
 * network switched off), and the generator's dependency tree was larger than the
 * application's. The build id and the precache list are injected at build time
 * by scripts/build-sw.mjs, which replaces the two placeholders below.
 *
 * Updating is never silent: a new worker waits until the user accepts the
 * update, so a version cannot change under them mid-row.
 */

const CACHE = 'crochet-studio-__BUILD_ID__'
const PRECACHE = __PRECACHE__

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE).then((cache) => cache.addAll(PRECACHE)),
    // No skipWaiting(): the page asks for it once the user agrees.
  )
})

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const names = await caches.keys()
      await Promise.all(
        names.filter((name) => name !== CACHE).map((name) => caches.delete(name)),
      )
      await self.clients.claim()
    })(),
  )
})

self.addEventListener('message', (event) => {
  if (event.data === 'SKIP_WAITING') self.skipWaiting()
})

self.addEventListener('fetch', (event) => {
  const request = event.request

  if (request.method !== 'GET') return

  const url = new URL(request.url)
  if (url.origin !== self.location.origin) return

  // Navigations: try the network so a new build is noticed, fall back to the
  // cached shell when offline. The app is a single page, so every route resolves
  // to index.html.
  if (request.mode === 'navigate') {
    event.respondWith(
      (async () => {
        try {
          return await fetch(request)
        } catch {
          const cache = await caches.open(CACHE)
          const cached = await cache.match('/index.html')
          return cached ?? Response.error()
        }
      })(),
    )
    return
  }

  // Everything else is a hashed, immutable asset: cache first, and keep anything
  // new that arrives (the lazily loaded 3D chunk, for example).
  event.respondWith(
    (async () => {
      const cache = await caches.open(CACHE)
      const cached = await cache.match(request)
      if (cached) return cached

      try {
        const response = await fetch(request)
        if (response.ok && response.type === 'basic') {
          cache.put(request, response.clone())
        }
        return response
      } catch (error) {
        // Offline and not in the cache: let the caller handle the failure.
        throw error
      }
    })(),
  )
})
